{
  "findings": [
    {
      "ref": "[D532]",
      "area": "contact",
      "claim": "A parent reports that Roblox allows voice or written text communication with other players after friend requests are made.",
      "stance": "risk",
      "quote": "Being an online game means that players in Roblox can interact and communicate with each other in various ways. This can be via voice or written text once friend requests have been made."
    },
    {
      "ref": "[D532]",
      "area": "contact",
      "claim": "A parent reports that voice chat on Roblox is restricted to eligible users and uses age verification and moderation technology.",
      "stance": "mitigation",
      "quote": "To help manage this, Roblox restricts voice chat features to eligible users and uses a combination of age verification, moderation technology and community reporting tools to identify and respond to harmful behaviour."
    },
    {
      "ref": "[D532]",
      "area": "contact",
      "claim": "A parent reports that users may encourage children to move conversations to other platforms like Discord or Instagram.",
      "stance": "risk",
      "quote": "Some users may encourage children to continue conversations on other platforms such as Discord, Snapchat, Instagram or WhatsApp."
    },
    {
      "ref": "[D532]",
      "area": "money",
      "claim": "A parent reports that many scams on Roblox promise free Robux, exclusive items or special rewards to collect account details or personal information.",
      "stance": "risk",
      "quote": "Many scams on Roblox promise free Robux, exclusive items or special rewards. These offers often aim to collect account details or personal information."
    },
    {
      "ref": "[D532]",
      "area": "money",
      "claim": "A parent reports that AI-generated scams on Roblox use realistic images, videos or messages to appear convincing and steal account details.",
      "stance": "risk",
      "quote": "As artificial intelligence (AI) tools become more widely available, scammers are finding new ways to make fake messages, websites and offers appear more convincing. On Roblox, children may come across promises of free Robux, exclusive items or special game benefits that look genuine but are designed to steal account details or personal information."
    },
    {
      "ref": "[D532]",
      "area": "data",
      "claim": "A parent reports that Roblox collects personal information through scams offering free Robux or exclusive items.",
      "stance": "risk",
      "quote": "Many scams on Roblox promise free Robux, exclusive items or special rewards. These offers often aim to collect account details or personal information."
    },
    {
      "ref": "[D532]",
      "area": "age_gating",
      "claim": "A parent reports that Roblox does not have a single age rating or minimum age because it hosts user-created content.",
      "stance": "neutral",
      "quote": "Unlike traditional video games, Roblox is a platform that hosts millions of user-created experiences. Because content is created and updated by users, Roblox does not have a single age rating or minimum age."
    },
    {
      "ref": "[D532]",
      "area": "age_gating",
      "claim": "A parent reports that Roblox uses Content Maturity Labels on all content and some features require age verification.",
      "stance": "mitigation",
      "quote": "Roblox uses Content Maturity Labels on all content on the platform. Some Roblox features and experiences require users to verify their age before they can access them."
    },
    {
      "ref": "[D532]",
      "area": "content",
      "claim": "A parent reports that a 10-year-old test account accessed highly suggestive spaces including games with private rooms and sexually suggestive outfits.",
      "stance": "risk",
      "quote": "Exploring as the 10-year-old, the team was able to access \"highly suggestive\" spaces. These included games featuring hotels with private rooms and characters dressed in \"sexually suggestive outfits.\""
    },
    {
      "ref": "[D532]",
      "area": "content",
      "claim": "A parent reports that a game called Boys and Girls Club Roleplay had a Content Maturity Level of Mild despite strong sexual undertones and accessibility for children.",
      "stance": "risk",
      "quote": "One game designed like a night club was called 'Boys and Girls Club Roleplay'. It had a Content Maturity Level of 'Mild' despite the \"strong sexual undertones\" and accessibility for children."
    },
    {
      "ref": "[D532]",
      "area": "developer_record",
      "claim": "A parent reports that Revealing Reality conducted a 2025 test using Roblox accounts for ages 5, 9, 10, 13 and 42 to examine age-based interactions.",
      "stance": "neutral",
      "quote": "An April 2025 report from Revealing Reality highlighted \"suggestive behaviours\" among other concerns. The research team created Roblox accounts for 5-, 9-, 10-, 13- and 42-year-olds to test the interactions of different users based on their age."
    }
  ]
}
